"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { pressDestructive, pressOutline, pressPrimary, pressSecondary } from "./_shared";

/**
 * Playful console IconButton: a single glyph on the same keys as Button.
 *
 * It is a square key by default, with the corner growing with its size; the
 * circle shape suits avatars and floating actions. The default is a white
 * key on a cream slab, primary is the orange key, and ghost stays flat for
 * toolbars and rows. A disabled key loses its slab and rests on cream.
 */
const iconButtonVariants = cva(
  [
    "relative inline-flex shrink-0 select-none items-center justify-center",
    "focus-visible:outline-2 focus-visible:outline-offset-3 focus-visible:outline-ring",
    "disabled:pointer-events-none disabled:translate-y-0 disabled:border-(--line-strong) disabled:bg-secondary disabled:text-(--foreground-disabled) disabled:shadow-none",
    "data-[disabled]:pointer-events-none data-[disabled]:translate-y-0 data-[disabled]:border-(--line-strong) data-[disabled]:bg-secondary data-[disabled]:text-(--foreground-disabled) data-[disabled]:shadow-none",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: pressOutline,
        primary: pressPrimary,
        secondary: pressSecondary,
        ghost:
          "bg-transparent text-foreground transition-colors duration-fast hover:bg-secondary data-[disabled]:bg-transparent",
        destructive: pressDestructive,
        outline: pressOutline,
      },
      size: {
        xs: "size-7 rounded-md [&_svg]:size-3.5",
        sm: "size-8 rounded-[0.5rem] [&_svg]:size-4",
        default: "size-10 rounded-[0.5rem] [&_svg]:size-5",
        lg: "size-12 rounded-[0.625rem] [&_svg]:size-6",
        xl: "size-14 rounded-[0.75rem] [&_svg]:size-6",
      },
      corners: {
        square: "",
        circle: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
      corners: "square",
    },
  },
);

/** Props for the IconButton. Give it an `aria-label`, since the glyph carries no text. */
export interface IconButtonProps
  extends
    Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof iconButtonVariants> {
  className?: string;
}

const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ className, variant, size, corners, ...props }, ref) => (
    <ButtonPrimitive
      ref={ref}
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, size, corners, className }))}
      {...props}
    />
  ),
);
IconButton.displayName = "IconButton";

export { IconButton, iconButtonVariants };
